INSERT INTO daily_analytics (user_id, date, total_calories, total_protein, total_carbs, total_fat) SELECT agg.user_id, agg.log_date, agg.total_calories, agg.total_protein, agg.total_carbs, agg.total_fat FROM (   SELECT user_id, timestamp::date AS log_date,          SUM(calories_consumed) AS total_calories,          SUM(protein_g) AS total_protein,          SUM(carbs_g) AS total_carbs,          SUM(fat_g) AS total_fat   FROM food_logs   GROUP BY user_id, timestamp::date ) agg WHERE NOT EXISTS (   SELECT 1 FROM daily_analytics da   WHERE da.user_id = agg.user_id AND da.date = agg.log_date );
